sys_script_include.script:
var MGI = Class.create();

/**
 * Provides the Eco Score response. This method must return a score key in the response:
 *  const writer = response.getStreamWriter();
 *  writer.writeString(JSON.stringify({ score: eco_score }));
 *
 * @param {sn_ws_int.RESTAPIRequest} request - The incoming REST API request object.
 * @param {sn_ws_int.RESTAPIResponse} response - The outgoing REST API response object used to send data back to the client.
 *
 * @returns {void}
 */
MGI.provideEcoScore = function(request, response) {
    var metric = "total_energy_consumption";

    //calculate score based on diff between location average and your metrics
    // Energy Score = 1 / (device total/country total) + 1
    // eco = energy

    const dh = new DeviceHealth();
    const user = dh.getUser();
    const devices = user.getDeviceValues("ECO");
    const country_avg = parseFloat(
        user.getCountryValues("ECO").values.total_energy_consumption,
    );

    if (!country_avg) return 0;

    const device_scores = [];

    //for each device calculate the diff between
    devices
        .filter((d) => d.values[metric])
        .forEach((device) => {
            const device_total = parseFloat(device.values[metric]);
            const score = 100 / (1 + device_total / country_avg);

            device_scores.push(Math.round(score));
        });

    eco_score =
        device_scores.reduce((sum, current) => sum + current, 0) /
        device_scores.length;

    response.setContentType("application/json");
    response.setStatus(200);

    const writer = response.getStreamWriter();
    writer.writeString(JSON.stringify({
        score: eco_score
    }));
};
